using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace Astera {
sealed partial class LibraryForm {
    readonly HashSet<string> robloxDetailsPending=new HashSet<string>();readonly HashSet<string> robloxChecked=new HashSet<string>();readonly System.Windows.Forms.Timer robloxLaunchClock=new System.Windows.Forms.Timer{Interval=1000};readonly HashSet<string> robloxStarting=new HashSet<string>();
    void StartRobloxLaunchGuard(){robloxLaunchClock.Tick+=delegate{bool refresh=false;foreach(string id in robloxStarting.ToArray()){DateTime until;if(!startingGames.TryGetValue(id,out until)||DateTime.UtcNow>=until){startingGames.Remove(id);robloxStarting.Remove(id);refresh|=IsRoblox&&CurrentCustom.Id==id;}}robloxLaunchClock.Enabled=robloxStarting.Count>0;if(refresh)RefreshRobloxView();};Disposed+=delegate{robloxLaunchClock.Dispose();};}
    bool IsRoblox {get{return IsCustomGame&&CurrentCustom.Platform=="roblox";}}
    void AddRoblox(){if(busy)return;using(var dialog=new AsteraDialog{Text="Add a Roblox experience",Size=new Size(650,300),StartPosition=FormStartPosition.CenterParent})using(var stop=new CancellationTokenSource()){
        var text=new TextBox{Left=20,Top=90,Width=600};var name=new TextBox{Left=20,Top=160,Width=600,MaxLength=100};var info=new Label{Left=20,Top=51,Width=600,Text="Paste an experience link or Place ID."};var label=new Label{Left=20,Top=130,Width=600,Text="Name (optional)"};var add=Button("Add experience",async delegate{long place;if(!RobloxSupport.TryParsePlaceId(text.Text,out place)){info.Text="Use a Roblox /games/ link or a positive Place ID.";return;}if(name.Text.Any(Char.IsControl)){info.Text="Use a name without control characters.";return;}var existing=store.Settings.CustomGames.FirstOrDefault(g=>g.Platform=="roblox"&&g.PlatformId==place.ToString());if(existing!=null){ReloadGames(existing);dialog.Close();return;}var game=new CustomGame{Platform="roblox",PlatformId=place.ToString(),Executable=RobloxSupport.WebUrl(place),Name=String.IsNullOrWhiteSpace(name.Text)?"Roblox experience "+place:name.Text.Trim()};foreach(Control c in dialog.Controls)if(c is Button)c.Enabled=false;info.Text="Finding experience details…";try{await LoadRobloxDetails(game,stop.Token);}catch(OperationCanceledException){return;}catch(Exception error){AsteraDiagnostics.Write("Roblox metadata unavailable; keeping manual shortcut",new IOException(error.GetType().Name));}if(dialog.IsDisposed||stop.IsCancellationRequested)return;store.Settings.CustomGames.Add(game);try{store.Save();}catch(Exception error){store.Settings.CustomGames.Remove(game);info.Text="Could not save the shortcut: "+error.Message;foreach(Control c in dialog.Controls)if(c is Button)c.Enabled=true;return;}ReloadGames(game);dialog.DialogResult=DialogResult.OK;dialog.Close();});add.SetBounds(440,215,180,38);dialog.Controls.AddRange(new Control[]{info,text,label,name,add});dialog.FormClosing+=delegate{stop.Cancel();};dialog.ShowDialog(this);
    }}
    async Task LoadRobloxDetails(CustomGame game,CancellationToken token){long place;if(!RobloxSupport.Positive(game.PlatformId,out place))throw new IOException("Invalid Roblox Place ID");var result=await Task.Run(delegate{var metadata=RobloxSupport.Lookup(place,token);string root=Path.Combine(store.Root,"artwork","roblox"),icon=null;var banners=new List<string>();try{icon=SteamPublicArtwork.Optional(()=>RobloxSupport.Cache(metadata.Icon,root,metadata.UniverseId,"icon",token),token);}catch(System.Net.WebException){token.ThrowIfCancellationRequested();}try{foreach(string url in metadata.Banners){token.ThrowIfCancellationRequested();string path=SteamPublicArtwork.Optional(()=>RobloxSupport.CacheGallery(url,root,metadata.UniverseId,token),token);if(path!=null)banners.Add(path);}}catch(System.Net.WebException){token.ThrowIfCancellationRequested();}return new{Metadata=metadata,Icon=icon,Banners=banners.ToArray()};});token.ThrowIfCancellationRequested();game.UniverseId=result.Metadata.UniverseId;if(game.Name=="Roblox experience "+place)game.Name=result.Metadata.Name;if(result.Icon!=null){game.RobloxIcon=result.Icon;CacheRobloxIcon(game);}game.RobloxBanners=result.Banners;game.RobloxBanner=result.Banners.FirstOrDefault()??"";game.RobloxArtworkVersion=2;game.RobloxArtworkCheckedUtc=DateTimeOffset.UtcNow.ToUnixTimeSeconds();}
    void CacheRobloxIcon(CustomGame game){if(!String.IsNullOrEmpty(game.RobloxIcon)&&File.Exists(game.RobloxIcon)&&!customIcons.ContainsKey(game.RobloxIcon))try{customIcons[game.RobloxIcon]=ReadCustomIcon(game.RobloxIcon);}catch(IOException){}catch(ArgumentException){}}
    async void QueueRobloxDetails(CustomGame game){if(previewMode||game==null||game.Platform!="roblox"||!IsRoblox||CurrentCustom.Id!=game.Id||!robloxChecked.Add(game.Id))return;CacheRobloxIcon(game);if(game.RobloxArtworkVersion>=2&&File.Exists(game.RobloxIcon)&&RobloxSlides(game).Length>0&&DateTimeOffset.UtcNow.ToUnixTimeSeconds()-game.RobloxArtworkCheckedUtc<86400)return;UpdatePublicArtworkSelection();var token=selectedPublicArtwork.Token;robloxDetailsPending.Add(game.Id);try{await LoadRobloxDetails(game,token);if(!IsDisposed&&store.Settings.CustomGames.Contains(game)){store.Save();games.Invalidate();if(IsRoblox&&CurrentCustom.Id==game.Id)RefreshRobloxView();}}catch(OperationCanceledException){robloxChecked.Remove(game.Id);}catch(Exception error){if(token.IsCancellationRequested){robloxChecked.Remove(game.Id);return;}if(!IsDisposed)AsteraDiagnostics.Write("Roblox details unavailable",new IOException(error.GetType().Name));}finally{robloxDetailsPending.Remove(game.Id);}}
    void RefreshRobloxView(){UpdateTransferSlot();var game=CurrentCustom;CacheCustomIcon(game);CacheRobloxIcon(game);appUpdateIcon.Enabled=!busy&&!checkingApp;banner.Game="custom";play.Text=GameStarting(game)?"STARTING…":"PLAY";((AsteraButton)play).Symbol=ButtonSymbol.Play;play.Enabled=!busy&&!GameStarting(game);check.Text="OPEN GAME PAGE";check.Enabled=!busy;download.Enabled=install.Enabled=restore.Enabled=cancel.Enabled=false;settings.Enabled=games.Enabled=!busy;status.Text="Managed by Roblox";status.ForeColor=Color.White;profileLabel.Text=RobloxSupport.WebUrl(Int64.Parse(game.PlatformId));releaseLabel.Text="Roblox experience shortcut";latestHeading.Text="Roblox";notes.Text="Roblox manages this experience and its client updates.";UpdateRobloxSlidePlayback();UpdateCustomLayout();heroSubtitle.Text="Open this experience in Roblox.";installationPath.Text="Place ID: "+game.PlatformId+"\r\nManaged by Roblox";openFolder.Enabled=false;QueueRobloxDetails(game);games.Invalidate();}
    void OpenRobloxPage(){if(!IsRoblox)return;long place;if(RobloxSupport.Positive(CurrentCustom.PlatformId,out place))Process.Start(new ProcessStartInfo(RobloxSupport.WebUrl(place)){UseShellExecute=true});}
    void LaunchRoblox(){if(!IsRoblox||GameStarting(CurrentCustom))return;var game=CurrentCustom;startingGames[game.Id]=DateTime.UtcNow.AddSeconds(10);try{Process.Start(RobloxSupport.LaunchInfo(game.PlatformId));TrackCustomLaunch(game);robloxStarting.Add(game.Id);robloxLaunchClock.Start();}catch(System.ComponentModel.Win32Exception){startingGames.Remove(game.Id);if(MessageBox.Show(this,"Roblox could not open. Open this experience's web page instead?","Roblox",MessageBoxButtons.YesNo)==DialogResult.Yes)OpenRobloxPage();}RefreshRobloxView();}
}
}
